(function (all) { var mine = all["pt-BR"] = all["pt-BR"] || {}; var add = {"manual.831d0f72d242":"Primeiros passos","manual.f2f53974b760":"O Freally Capture é um estúdio para desktop no Windows, no macOS e no Linux. Este manual descreve a versão 1.2.1, a versão atual.","manual.4b5f10daa08b":"Abra o Freally Capture. Na primeira vez, ele pede que você aceite o contrato de licença; depois, um assistente de configuração verifica sua placa de vídeo e seu processador e propõe um codificador, um tamanho de tela e um bitrate, com o motivo de cada escolha.","manual.fe88634050bf":"O estúdio abre na prévia do programa, com as docas <strong>Cenas</strong>, <strong>Fontes</strong>, <strong>Mixer</strong> e <strong>Controles</strong>. Não há conta nem login.","manual.4c937d2528ca":"No <strong>macOS</strong>, permita a <strong>Gravação de Tela</strong> — e também <strong>Câmera</strong> e <strong>Microfone</strong>, se for usá-los — em Ajustes do Sistema → Privacidade e Segurança, e depois abra o app de novo. No <strong>Linux com Wayland</strong>, a própria caixa de diálogo do sistema pergunta qual tela ou janela compartilhar.","manual.adc8f305f8f8":"Adicione sua primeira fonte (veja <a href=\"#build-a-scene\">Montar uma cena</a>) e você estará pronto para gravar ou entrar ao vivo.","manual.46e49bd74b1d":"Montar uma cena","manual.f779d891c1f2":"Uma cena é uma pilha de fontes compostas na placa de vídeo. Uma fonte pode ser compartilhada por várias cenas.","manual.5a1c5f778fdb":"Na doca <strong>Fontes</strong>, clique em <strong>Adicionar fonte</strong> e escolha um tipo: <strong>Tela</strong>, <strong>Janela</strong>, <strong>Jogo</strong>, <strong>Webcam / Placa de captura</strong>, <strong>Navegador</strong>, <strong>Mídia</strong>, <strong>Imagem</strong>, <strong>Texto</strong>, <strong>Cor</strong> ou <strong>Áudio</strong>.","manual.2a2d9e2015b5":"Adicione uma <strong>Captura de Tela</strong>: a prévia do programa se enche com a sua tela.","manual.80c8e9c8176f":"Adicione uma fonte de <strong>Webcam</strong>, arraste-a para um canto da tela e redimensione-a pelas alças.","manual.264150f36676":"Adicione por cima uma sobreposição de <strong>Imagem</strong> ou de <strong>Navegador</strong>. A ordem da lista é a ordem na tela: o topo da lista fica na frente.","manual.a329c46899d6":"Crie mais cenas na doca <strong>Cenas</strong> — por exemplo, “Começando em breve”, “Gameplay” e “Volto já” — e alterne entre elas.","manual.9c8d5730d1bb":"<strong>Dica:</strong> mude uma vez as propriedades de uma fonte compartilhada e ela muda em todas as cenas que a usam.","manual.fd869e76d280":"<strong>A prévia:</strong> no Windows, no macOS e no Linux com X11, a prévia do programa é pintada direto pela placa de vídeo, então arrastar, escalar e girar parecem instantâneos. No Wayland é usada uma prévia padrão, com a mesma edição na tela.","manual.87eca68fecaa":"Filtros e transições","manual.36a962cf3902":"Empilhe filtros em cada fonte, na placa de vídeo, e escolha como uma cena dá lugar à seguinte.","manual.4708b4dbab34":"Adicionar um chroma key","manual.9df34cebcaf5":"Clique com o botão direito numa fonte — uma câmera diante de uma tela verde, por exemplo — e escolha <strong>Filtros</strong>.","manual.9981601a6174":"Adicione <strong>Chroma Key</strong> e ajuste a <strong>Cor-chave</strong>, a <strong>Similaridade</strong>, a <strong>Suavidade</strong> e o <strong>Vazamento</strong>: a cor recortada desaparece ao vivo na tela.","manual.b76bd309a9f6":"Adicione mais filtros conforme precisar — <strong>Correção de Cor</strong>, <strong>LUT</strong>, <strong>Desfoque</strong>, <strong>Máscara</strong>, <strong>Nitidez</strong> — e arraste-os para reordenar a cadeia.","manual.db41fe5a40e4":"Definir uma transição","manual.bea9e11be98d":"Em <strong>Controles</strong>, abra o seletor de transições, escolha <strong>Corte</strong>, <strong>Esmaecer</strong>, <strong>Deslizar</strong>, <strong>Varrer</strong>, <strong>Stinger</strong> ou <strong>Cortina luma</strong> e defina uma duração.","manual.eada58ce5b2e":"Para um <strong>Stinger</strong>, escolha a mídia e o ponto de transição; para uma <strong>Cortina luma</strong>, escolha o gradiente e a suavidade dele.","manual.79756cb8b209":"Troque de cena para ver a transição acontecer. No Modo Estúdio, ela acontece quando você envia a prévia para o programa.","manual.2c0c025b4264":"Compositor e efeitos visuais","manual.b768e85eff32":"Inclinação 3D, keyers de saída, congelamento e clonagem, uma família de desfoques, transições de movimento com regras, um estúdio de shaders, máscaras Bézier e stingers com track matte.","manual.d2b720eca5a5":"Inclinação 3D e perspectiva","manual.d665cc2f2296":"Abra <strong>Editar transformação…</strong> num item e defina <strong>Inclinação X</strong>, <strong>Inclinação Y</strong> e uma intensidade de <strong>Perspectiva</strong> para posicionar a fonte em 3D. Uma transformação sem inclinação é renderizada exatamente como antes.","manual.c4077ba2b72d":"Keyers de saída","manual.d4220af54ed9":"Abra <strong>Ferramentas → Keyers de saída…</strong> e adicione qualquer fonte como uma camada sobre a <strong>Saída do programa</strong>, acima de todas as cenas e através de todas as trocas de cena — um logo da emissora, um selo AO VIVO, um lower third.","manual.0677e571c1f8":"Reordene as camadas e defina a opacidade, a posição, o tamanho e o liga/desliga de cada uma. Elas aparecem igualmente na prévia, na gravação, na transmissão e na multivisualização.","manual.1e484119e149":"Congelamento de quadro e clonagem de fontes","manual.4cdb8e22f58b":"Clique com o botão direito numa fonte, abra <strong>Filtros</strong> e adicione <strong>Congelar</strong>: ele segura o último quadro no programa, na prévia, na gravação e na transmissão ao mesmo tempo. Desative-o para descongelar.","manual.59fd957b48dc":"Clique no botão <strong>Clonar</strong> (⧉) na linha de uma fonte para colocar um mesmo sinal em várias cenas ou posições, cada clone com sua própria transformação e seus próprios filtros.","manual.a90410d6b30c":"Desfoques","manual.eeb69e428aa3":"Nos <strong>Filtros</strong> de uma fonte, adicione um dos desfoques ao lado do gaussiano: <strong>direcional</strong> (um rastro de movimento num ângulo), <strong>radial</strong> (um giro em torno de um centro), <strong>zoom</strong> (um rastro de dolly zoom) ou <strong>pixelizar</strong> (um mosaico).","manual.54261c9f6b8f":"A transição de movimento e as regras de transição","manual.ef17a04962be":"Escolha a transição <strong>Movimento</strong> (Move): os itens presentes nas duas cenas deslizam da posição, escala, rotação e recorte antigos para os novos em vez de cortar, e os itens que estão em só uma das cenas aparecem ou somem com fade.","manual.e31792f9e737":"Abra <strong>Ferramentas → Regras de transição…</strong> para dar a um par de cenas sua própria transição e duração. Para a entrada de um item específico, defina um fade-in de <strong>Revelação</strong> em <strong>Editar transformação…</strong>.","manual.bb4e30a1ea68":"O estúdio de shaders WGSL","manual.e475acf03bea":"Adicione um <strong>efeito WGSL do usuário</strong> como filtro e edite-o ao vivo. Os controles deslizantes dele são criados a partir de anotações <code>// @param</code>, e uma galeria embutida traz tons de cinza, inverter, linhas de varredura e vinheta.","manual.424ca3316822":"<strong>Dica:</strong> um shader é compilado e verificado enquanto você digita. Um shader inválido é ignorado e a fonte é renderizada sem o filtro — nunca um travamento.","manual.c24e8b5ee2c0":"Máscaras Bézier","manual.37870edaacbc":"Adicione o filtro <strong>máscara à mão livre</strong> e desenhe um caminho fechado: arraste as alças, clique duas vezes para adicionar um ponto, clique com o botão direito para remover um. Ele tem formas predefinidas, suavização para cada borda e inversão.","manual.f44ad1306530":"Exporte qualquer caminho como um padrão de <strong>cortina luma</strong> em tons de cinza para reaproveitar a forma como transição.","manual.e4c8b0c52b3e":"Stingers com track matte","manual.b35494db6ce6":"Configure um stinger para levar sua transparência como um <strong>Track matte</strong>, com o preenchimento e o matte <strong>Lado a lado</strong> ou <strong>Empilhado</strong>, para que a transparência sobreviva a codecs que a descartam (H.264 e HEVC). Opcionalmente, <strong>abaixe o áudio do programa</strong> sob o som do próprio stinger enquanto ele toca.","manual.3879f0c73d18":"Sobreposições e mais fontes","manual.cea21c089e39":"Replay, playlists, títulos, medidores, uma sobreposição de estatísticas, timers, uma sobreposição de entradas e dois sinais de rede, tudo pelo menu <strong>+ / Adicionar fonte</strong> da doca <strong>Fontes</strong>.","manual.4a459b922e4b":"Replay instantâneo","manual.2e042aa67065":"Primeiro arme o buffer de replay (<strong>Armar replay</strong> na doca <strong>Controles</strong>), depois escolha <strong>Replay instantâneo</strong> em <strong>+ / Adicionar fonte</strong> e posicione-o numa cena.","manual.d7645da473a6":"Leve os últimos segundos para o programa com seu atalho de replay — copiados sem recodificar e reproduzidos a <strong>100%</strong>, <strong>50%</strong> ou <strong>25%</strong> da velocidade, desacelerados em vez de com quadros inventados. Avance, volte ou pause enquanto toca.","manual.5b8095e70de0":"No fim, a fonte se limpa sozinha, então o programa volta à imagem ao vivo por conta própria.","manual.6433eaab9b10":"<strong>Dica:</strong> o replay em câmera lenta é mudo de propósito: o áudio desacelerado ficaria borrado, então ele fica de fora em vez de ser fingido.","manual.f0b63d46cd74":"Playlist de mídia e música de fundo","manual.37ed12f9d130":"Adicione <strong>Playlist de mídia (sem cortes)</strong> e monte uma lista ordenada com pontos de entrada e saída e pontos de deixa para cada item. A lista inteira toca por um único decodificador, então as emendas são exatas no quadro e realmente sem pausas.","manual.ef41fa6ad9b5":"Escolha como ela roda — <strong>Repetir</strong>, <strong>Aleatório</strong> ou <strong>manter o último</strong> — e avance por ela com os atalhos de próximo e anterior. Uma playlist só de áudio mostra o <strong>nome da faixa atual</strong> na tela e toca pelo seu próprio canal no mixer; clique no botão <strong>Monitor</strong> desse canal para ouvi-la.","manual.6e641ae2bd92":"Para música que toca sem nada na tela, escolha <strong>+ / Adicionar fonte → Música de fundo…</strong> e selecione um ou mais arquivos <code>.mp3</code>, <code>.wav</code> ou <code>.flac</code>, em ordem aleatória se quiser. Ela silencia o som próprio de um fundo de vídeo, para que só uma coisa seja ouvida por vez.","manual.b9aad55133bf":"O editor de títulos e placares","manual.5382c093aaef":"Adicione <strong>Título / Placar</strong> para abrir o editor: empilhe camadas de <strong>Texto</strong>, <strong>Imagem</strong> e <strong>Forma</strong>, com texto com contorno e sombra e animações de entrada e saída (fade, deslizar, cortina).","manual.7b8fea70655a":"Vincule campos a um arquivo monitorado (uma célula de CSV ou um ponteiro JSON) ou a uma variável do estúdio e controle tudo ao vivo: troque um nome, edite o placar ou dispare a animação sem mexer na cena.","manual.88a9422e37a9":"O visualizador de áudio","manual.87f4a5bdd624":"Adicione <strong>Visualizador de áudio</strong> e escolha um estilo — <strong>Barras de espectro</strong>, um <strong>Osciloscópio</strong> ou <strong>Medidores VU</strong> estéreo — e vincule-o a qualquer canal do mixer, faixa ou ao mix master. Ele também mostra o som de um vídeo de fundo.","manual.0ae90a461adb":"Nas <strong>Propriedades</strong> da fonte, ative <strong>Cores clássicas</strong> para as faixas verde, amarela e vermelha, ou deixe desligado para uma única cor sólida. Tamanho, número de barras e velocidade de queda também ficam lá.","manual.0d1ceffb08ba":"<strong>Dica:</strong> o visualizador escuta <strong>depois do fader</strong>, então uma fonte silenciada aparece achatada: ele mostra exatamente o que você ouve.","manual.ec642e1cf0cc":"A sobreposição de estatísticas, o timer de splits e a sobreposição de entradas","manual.6b4fe6f81cb0":"Adicione <strong>Estatísticas de desempenho (HUD)</strong> para mostrar na tela os números medidos da doca de estatísticas — quadros por segundo, CPU, memória, tempo de composição na GPU, quadros perdidos e bitrate ao vivo —, cada linha ligada ou desligada. O uso da GPU fica de fora de propósito, porque não é medido.","manual.cbd8a4b88736":"Adicione <strong>Timer de splits (speedrun)</strong>, importe um arquivo <code>.lss</code> do LiveSplit e rode-o com atalhos globais de split, desfazer, pular e reiniciar, comparando com seu recorde pessoal, seus melhores segmentos ou a média. O arquivo é só lido; uma run nunca é gravada de volta.","manual.fbf4bbeaf903":"Adicione <strong>Sobreposição de entradas (teclas/controle)</strong> para mostrar ao vivo o teclado, o mouse e o gamepad, num de quatro layouts (WASD, teclado compacto, controle de dois analógicos, arcade stick de 8 direções). Teclado e mouse funcionam no Windows; gamepads funcionam nos três sistemas.","manual.bf794edb3c25":"A barra de redes sociais e canais","manual.5f898056ef11":"Adicione <strong>Barra de redes sociais</strong> em <strong>+ / Adicionar fonte</strong>: um painel que lista seus perfis. Escolha uma plataforma para cada linha — <strong>YouTube, Twitch, Kick, X, Instagram, TikTok, Facebook, Discord</strong> como selos coloridos, ou <strong>Personalizado</strong> com seu próprio rótulo e cor — e digite o perfil (por exemplo, <code>@mychannel</code>). Adicione uma linha de cabeçalho opcional (“Me siga”), reordene as linhas e defina o tamanho e as cores do texto.","manual.1dab9389547a":"Todos os campos continuam editáveis nas <strong>Propriedades</strong> da fonte. Linhas sem perfil são puladas, então você pode manter uma lista completa e preencher só o que usa.","manual.1a4ac3c2e0bf":"A mensagem de chat em destaque","manual.c5d58a7d58be":"Abra <strong>Ferramentas → Mensagem de chat em destaque…</strong> (ou a paleta de comandos). Ela lista as linhas mais recentes de todas as sobreposições de chat em execução: clique em <strong>Destacar</strong> numa delas para fixá-la no programa como um banner que quem assiste à transmissão e à gravação vê.","manual.162d364796a2":"Defina as cores do <strong>banner</strong> e do <strong>Texto</strong> na caixa de diálogo e clique em <strong>Remover</strong> para tirá-la do ar. A fixação em si é desfeita ao reiniciar, de propósito: o destaque de ontem nunca assombra o programa de hoje.","manual.89a84c53e014":"Destaque do cursor e efeitos de clique","manual.d0a5d9fb047d":"Clique com o botão direito numa captura de Tela ou de Janela, abra <strong>Filtros</strong> e adicione <strong>Efeitos do cursor</strong>: um <strong>Halo do cursor</strong> (cor e raio), <strong>Ondas de clique</strong> com cores diferentes para o botão esquerdo e o direito e <strong>Teclas fantasma</strong> opcionais ao lado do ponteiro. As mudanças aparecem ao vivo.","manual.4a17c44757e4":"<strong>Observação:</strong> os efeitos de cursor funcionam só no Windows; o macOS e o Linux desenham o próprio cursor. A sobreposição de entradas e as teclas fantasma leem a entrada <strong>só enquanto estão ligadas</strong> e a desenham direto na imagem: nada é guardado nem registrado.","manual.8bdb1aadf964":"Fontes de rede: recepção pela LAN e Freally Link","manual.797fe86a1fe8":"Adicione <strong>Recepção pela LAN (receptor SRT/RTMP)</strong> para abrir um receptor neste computador e aponte um app de câmera de celular, um codificador ou um segundo computador para o endereço mostrado (com um QR code). O sinal chega à cena com seu próprio canal no mixer. O SRT pode levar uma senha AES opcional; o RTMP não tem autenticação própria, então o formulário prefere o SRT.","manual.e2761818ccef":"Para compartilhar entre duas cópias do Freally Capture, ative a saída <strong>Freally Link</strong> no computador que <strong>envia</strong> e defina a <strong>Chave de pareamento</strong> dela — ela não pode ser ativada sem uma. No computador que <strong>recebe</strong>, adicione <strong>Freally Link (outra instância)</strong>, clique em <strong>Varrer a LAN</strong> e digite a chave: o programa de quem envia aparece como uma fonte. Nenhum dos lados precisa do ffmpeg, e um receptor sem a chave nunca vê um quadro.","manual.a793cb271e32":"<strong>Observação:</strong> as duas fontes de rede ficam <strong>desligadas até você adicioná-las</strong>, permanecem na sua própria rede e nunca tocam a internet: nada encontra você e nada se conecta para fora.","manual.de10be5dcf2c":"A contagem regressiva “Começando em breve”","manual.71b47ef78ea4":"Uma tela de espera antes do programa em um clique: uma grande contagem regressiva até a hora do programa sobre uma imagem, um GIF, um vídeo, um gradiente ou música, que pisca no zero e espera você cortar para o programa.","manual.303493002776":"Adicionar a contagem regressiva","manual.f78f2994b5d5":"Na doca <strong>Fontes</strong>, abra <strong>+ / Adicionar fonte</strong> e escolha <strong>Começando em breve…</strong>. Ela coloca na cena uma contagem regressiva em tela cheia — uma legenda sobre um número grande.","manual.c4bff5a4f06e":"Digite a <strong>legenda</strong> (“Começando em breve”, “Volto já”) e defina o horário com o <strong>seletor de relógio</strong>: uma <strong>hora</strong> (1–12), um <strong>minuto</strong> em passos de cinco minutos e <strong>AM</strong> ou <strong>PM</strong>. A fonte faz a contagem regressiva até esse horário do dia.","manual.59b00df516f1":"No zero, a contagem regressiva <strong>pisca e fica parada em 0:00:00</strong> — ela nunca troca de cena sozinha. Corte para a sua cena ao vivo quando estiver pronto. Todos os campos continuam editáveis nas <strong>Propriedades</strong> da fonte.","manual.1dfb2d817d39":"Escolher um fundo","manual.edc2450aeecd":"Escolha o preenchimento: um <strong>Gradiente</strong> de duas cores (o padrão), uma cor <strong>Sólida</strong>, uma <strong>Imagem</strong> (clique em <strong>Procurar…</strong>) ou <strong>Transparente</strong>, para deixar aparecer uma fonte que está por baixo.","manual.07a5fd9ac032":"Escolha um arquivo <strong>GIF</strong> ou de <strong>Vídeo</strong> e ele fica em loop atrás dos números, <strong>ajustado para caber e centralizado</strong>, para que a imagem inteira apareça e nada seja recortado.","manual.1cda5be75376":"Adicione <strong>Música de fundo</strong> pelo <strong>Procurar…</strong> da caixa de diálogo (MP3, WAV, FLAC, M4A, AAC, OGG ou Opus). Ela fica em loop, você a ouve na prévia e ela faz parte da gravação e da transmissão. O som próprio de um fundo de vídeo é silenciado, para que só uma coisa seja ouvida por vez.","manual.b39b6b7add20":"<strong>Dica:</strong> para ter música atrás de uma tela simples, deixe o fundo em Gradiente ou Transparente e adicione a música: uma contagem regressiva limpa com trilha sonora.","manual.84f506f4fca5":"O mixer de áudio","manual.480e299c8728":"Mixe todas as fontes de áudio, envie-as para até 6 faixas e limpe o som do seu microfone — tudo ao vivo.","manual.bcbc220b3e63":"Cada fonte de áudio é um canal no <strong>Mixer</strong>: o nome, um medidor de nível, um fader, silenciar, monitor, filtros e os pontos de faixa (1–6).","manual.03b920dc5376":"Arraste um fader para definir o nível, clique em <strong>Silenciar</strong> ou <strong>Monitor</strong> e envie a fonte para qualquer uma das 6 faixas.","manual.9a9991c7dc36":"Abra os <strong>Filtros</strong> de uma fonte e adicione <strong>Redução de Ruído</strong> (processamento de sinal clássico, sem IA), <strong>Noise Gate</strong>, <strong>Compressor</strong>, <strong>Limitador</strong>, <strong>EQ</strong> ou <strong>Ganho</strong>.","manual.1a58b91bc5aa":"Defina um atalho de <strong>Push-to-talk</strong> ou de <strong>Push-to-mute</strong> e acompanhe o medidor <strong>LUFS</strong> para ver o loudness do programa.","manual.7158a36ed4d5":"<strong>Observação sobre o macOS:</strong> o macOS não entrega aos apps “o que você ouve” por conta própria. Use o áudio do ScreenCaptureKit (macOS 13 ou posterior) quando estiver disponível, ou instale um dispositivo virtual como o BlackHole e escolha-o como sua fonte de áudio do sistema. O Freally Capture orienta você e continua gravando mesmo que uma fonte não consiga abrir.","manual.bfdd510698ef":"Gravar","manual.e39b756fce99":"Grave o programa em várias faixas com o codificador de hardware da sua placa de vídeo, ou sem perdas no formato próprio do Capture.","manual.ad438c2dbf4b":"Em <strong>Configurações → Saída</strong>, escolha um codificador. O Freally Capture encontra <strong>NVENC</strong>, <strong>Quick Sync</strong>, <strong>AMF</strong>, <strong>VAAPI</strong> ou <strong>VideoToolbox</strong> e escolhe o melhor; o <strong>x264</strong> no processador está sempre lá como alternativa.","manual.3bc1870f8449":"Escolha um contêiner — <strong>MP4</strong>, <strong>MKV</strong>, <strong>MOV</strong> ou <strong>WebM</strong> — ou o formato sem perdas próprio do Capture, o <strong>freally-video</strong> (<code>.frec</code>), que não precisa de mais nada instalado.","manual.e2a332927058":"Envie as fontes para faixas de áudio (até 6) para que o microfone, o som do sistema e seus convidados fiquem separados na edição. Opcionalmente, ative a <strong>divisão de arquivos</strong> e <strong>uma cópia local com faixas separadas durante a transmissão</strong>.","manual.e0fa2f5a9430":"Clique em <strong>Iniciar gravação</strong> em <strong>Controles</strong>. Um ponto verde <strong>REC</strong> mostra o tempo e o número de faixas. Clique em <strong>Parar</strong> para finalizar o arquivo.","manual.b1eb969490f1":"<strong>Observação sobre codecs:</strong> o MP4 com H.264 e AAC (e HEVC ou AV1) usa codecs protegidos por patentes, fornecidos pelo <strong>ffmpeg</strong>, que <em>não vem embutido</em>: o Freally Capture o baixa na primeira vez que você precisa dele e o verifica. O formato sem perdas <strong>freally-video</strong> não precisa de nenhum download.","manual.691bff5377a8":"Gravação e replay a fundo","manual.3c2d08430816":"Tudo em torno do arquivo: gravações separadas de cada fonte, um cortador de clipes, transparência de verdade, divisão e marcadores em eventos, tarefas após a gravação, uma verificação de integridade e timecode SMPTE. Tudo fica desligado até você ligar, e nada disso vai para a internet.","manual.537ffa2b9063":"Gravação ISO por fonte","manual.e57aa725fa41":"Abra <strong>Configurações → Saída</strong> e encontre <strong>Gravação ISO</strong>. Ative <strong>Gravar “{name}” como arquivo ISO próprio</strong> para cada fonte que você quer limpa: cada uma é gravada antes da composição, no tamanho e na taxa de quadros da tela, para que todo arquivo fique alinhado com o programa numa linha do tempo de edição. Cada convidado remoto é uma fonte, então cada convidado também ganha um arquivo.","manual.4bce8f25ec9c":"Deixe <strong>Gravar com os filtros da fonte</strong> marcado para o visual processado, ou desmarque para a fonte crua, e escolha o <strong>Formato ISO</strong> e o <strong>Codificador de vídeo ISO</strong> de cada gravação. O áudio é captado depois dos filtros, mas antes do fader e do silenciamento, então uma decisão de mixagem nunca deixa um arquivo ISO mudo.","manual.7f29ae4e2c55":"<strong>Dica:</strong> duas gravações ISO rodam com folga numa placa de vídeo intermediária; cada uma a mais custa outra renderização e outra codificação, e o painel avisa isso.","manual.b2aad668b8b9":"O cortador de replays e clipes","manual.c8af16e1cd4f":"Abra uma gravação salva na janela <strong>Aparar</strong> a partir da lista de gravações, avance por ela com <strong>Um quadro para trás</strong> e <strong>Um quadro para frente</strong> e marque seus pontos com <strong>Ponto de entrada</strong> e <strong>Ponto de saída</strong> enquanto assiste.","manual.1f80dfd03a36":"Confira o selo antes de exportar. Um verde <em>“Exporta sem recodificar”</em> significa que o ponto de entrada está num quadro-chave (quase instantâneo e sem perdas); o selo âmbar avisa que haverá recodificação — aperte <strong>Quadro-chave</strong> para encaixar o ponto de entrada e ter um corte sem perdas. Clique em <strong>Exportar clipe</strong>, ou em <strong>9:16</strong> para exportar uma versão vertical.","manual.8a92b0b480f4":"Gravar com transparência","manual.79bfd450e6aa":"Em <strong>Configurações → Saída</strong>, ative <strong>Gravar com transparência (alfa)</strong> para gravar o programa sobre um fundo transparente no formato <code>.frec</code> do Capture. A gravação ganha sua própria renderização transparente, então sua prévia e sua transmissão mantêm a imagem normal. Na lista de gravações, exporte um <code>.mov</code> em <strong>ProRes 4444</strong> ou <strong>QuickTime Animation (QTRLE)</strong> para o seu editor; MP4 e MKV achatam a transparência.","manual.fade0a9d0454":"<strong>Observação:</strong> a transparência é só uma flag no cabeçalho do <code>.frec</code>, então esses arquivos tocam em qualquer lugar onde o <code>.frec</code> toca, e arquivos mais antigos abrem como opacos.","manual.33e5c9a96c5d":"Divisão e marcadores automáticos","manual.5596d47693a3":"Nas configurações de divisão do <code>.frec</code>, escolha começar um novo arquivo ao <strong>trocar de cena</strong>, num <strong>marcador</strong> ou num <strong>passo do roteiro</strong>. Cada parte começa no quadro exato desse evento, e uma parte dura pelo menos um segundo, então uma rajada de eventos não gera uma pilha de arquivos minúsculos.","manual.7fc20a49c196":"Ative <strong>Inserir marcadores de capítulo automaticamente em eventos do estúdio</strong> para marcar como capítulos as trocas de cena, os replays salvos, as reconexões, as rajadas de quadros perdidos, os alarmes e as ações de regras. Eles vão para os títulos de capítulo do MKV e para o arquivo <code>.chapters.txt</code> ao lado da gravação, junto com os marcadores que você coloca com seu atalho.","manual.519fceb746f3":"Depois de gravar: o pipeline e a verificação de integridade","manual.561bb55d7a18":"Monte um <strong>Pipeline pós-gravação</strong> para cada perfil a partir de um conjunto fixo de passos — <strong>Verificar</strong>, <strong>Remuxar para MP4</strong>, <strong>Normalizar volume</strong>, <strong>Renomear</strong>, <strong>Mover para pasta</strong>, <strong>Copiar para pasta</strong>, <strong>Mostrar no gerenciador de arquivos</strong> e <strong>Notificar scripts Lua</strong>. Ele roda em segundo plano com uma fila ao vivo e para na primeira falha. De propósito, não existe um passo “executar qualquer comando”.","manual.2f93cddd1f21":"Rode a verificação de integridade depois de uma gravação ou quando quiser, para um resultado claro — OK, aviso ou falha — sobre <strong>Contêiner</strong>, <strong>Continuidade de vídeo</strong>, <strong>Continuidade de áudio</strong>, <strong>Intercalação de áudio e vídeo</strong> e <strong>Duração</strong>. Arquivos <code>.frec</code> passam pela verificação profunda; os outros arquivos passam por uma verificação de estrutura e de decodificação pelo ffmpeg.","manual.0d291aee5546":"Exportar uma cópia compartilhável ao parar","manual.124d2a00ed27":"Em <strong>Configurações → Saída</strong>, com o contêiner em <code>.frec</code>, marque <strong>Salvar também um MP4 compartilhável ao lado do master</strong>. Quando uma gravação termina, uma exportação em segundo plano grava, ao lado do master sem perdas, um <code>.mp4</code> que qualquer pessoa consegue reproduzir.","manual.a37303723389":"A cópia aparece na fila pós-gravação, recebe um nome que nunca sobrescreve nada e nunca toca no master. A opção fica desligada até você ligá-la.","manual.7ed8656eb1ff":"Timecode SMPTE LTC","manual.3d97874c3064":"Abra <strong>Timecode SMPTE (LTC)</strong>, ative <strong>Gerar LTC em uma faixa</strong> e escolha a faixa do mixer e a taxa de quadros para alimentar gravadores e câmeras externos. Defina <strong>Ler LTC de</strong> como uma entrada de áudio para mostrar uma linha de timecode na sobreposição de estatísticas e inserir marcadores de capítulo LTC. Timecode de áudio clássico, totalmente offline, com precisão de um quadro a 24, 25 e 30 fps.","manual.a9f690169703":"Entrar ao vivo","manual.8f6df4580812":"Transmita direto do seu computador para uma plataforma por RTMP ou RTMPS — nunca por um servidor nosso.","manual.dba22b61cdcc":"Abra <strong>Configurações → Transmissão</strong> e clique em <strong>Adicionar destino</strong>. Escolha <strong>Twitch</strong>, <strong>YouTube</strong>, <strong>Kick</strong>, <strong>Facebook</strong>, <strong>Trovo</strong> ou <strong>RTMP personalizado</strong>.","manual.2192731aac47":"Cole sua <strong>chave de transmissão</strong> — guardada no seu computador e exibida mascarada — e defina o bitrate e o codificador para esse serviço.","manual.040014e94f16":"Clique em <strong>Ficar ao vivo</strong> em <strong>Controles</strong>. A luz <strong>AO VIVO</strong> acende, e a doca de estatísticas mostra seu bitrate, os quadros perdidos e a saúde da transmissão.","manual.0cd441959cb4":"Se a sua conexão cair, o Freally Capture <strong>se reconecta sozinho</strong>, e a sua gravação local continua, aconteça o que acontecer com a transmissão. Defina um <strong>atraso da transmissão</strong> se quiser.","manual.dc8ebcea4893":"Clique em <strong>Encerrar transmissão</strong> para parar.","manual.973adc03e43c":"Segurança no ar","manual.53fa9293a65e":"Não perder o programa — antes, durante e depois.","manual.de8792b14216":"Antes: a checagem antes da live","manual.ed9a4b7bfaf5":"Clicar em <strong>Ficar ao vivo</strong> primeiro executa uma lista de verificação: os destinos de transmissão têm chave, há um codificador utilizável, todas as fontes estão saudáveis e há espaço em disco suficiente para a gravação — cada item verde ou vermelho, com uma correção em um clique —, além de lembretes sobre os níveis do microfone e do áudio da área de trabalho e sobre o buffer de replay, que nunca bloqueiam um programa só de tela. Uma configuração pode <strong>segurar o Ficar ao vivo até que todas as verificações bloqueantes estejam verdes</strong>; caso contrário, há a opção “Ficar ao vivo mesmo assim”.","manual.9b63c5c64ba1":"Durante: alarmes, saúde e troca automática","manual.9c386b745073":"Os <strong>alarmes de segurança</strong> vigiam enquanto você está ao vivo ou gravando: áudio do programa em silêncio, clipping contínuo, imagem preta ou congelada e uma <em>previsão</em> de disco cheio (“cerca de 22 minutos restantes no bitrate atual”). Eles aparecem como um banner que você pode dispensar, e os leitores de tela os anunciam — nunca uma caixa de diálogo que interrompe o programa.","manual.b7c8c66a5330":"O <strong>painel de saúde das fontes</strong> (paleta de comandos → “Saúde das fontes…”) lista o estado de cada fonte, a taxa de quadros, a idade do último quadro, os quadros perdidos e os reinícios, com <strong>Reiniciar</strong> e <strong>Propriedades</strong> para cada uma.","manual.92bd60ef963b":"Se o codificador de hardware falhar no meio de uma transmissão ou gravação — um reset do driver, a placa de vídeo sobrecarregada —, a <strong>troca automática de codificador</strong> passa para outro codificador de hardware ou para o x264. A transmissão se reconecta e continua no ar, a gravação continua num novo arquivo, e uma mensagem diz exatamente o que aconteceu. Problemas de rede nunca causam uma troca.","manual.50a02fe4fe7b":"O <strong>botão de pânico</strong> (um atalho global que você escolhe) corta o programa — e a tela vertical e os projetores — para uma tela de privacidade, interrompe todas as capturas e silencia todo o áudio, inclusive o microfone, enquanto a transmissão e a gravação continuam conectadas. Para voltar, é preciso uma confirmação deliberada em duas etapas. Defina a cor ou a imagem dessa tela ao lado do atalho em <strong>Configurações → Atalhos</strong>.","manual.a73a2857361e":"Depois: gravações seguras e um encerramento ordenado","manual.bf07b060e7e7":"As gravações em MP4 e MOV são gravadas em <strong>fragmentos</strong>, então um travamento ou uma queda de energia ainda deixa um arquivo reproduzível (MKV e <code>.frec</code> já eram assim). Se uma sessão terminar no meio de uma gravação, a próxima abertura oferece <strong>Reparar</strong> com um clique, gerando uma cópia <code>(repaired)</code>; o original nunca é tocado.","manual.da5eeb31c1b8":"Sair enquanto está ao vivo, gravando ou com o replay armado mostra o que vai acontecer e depois encerra <strong>em ordem</strong>: termina a transmissão, finaliza a gravação, salva o buffer de replay e salva o seu trabalho.","manual.26b3f2c32e05":"Os <strong>nomes dos arquivos de gravação</strong> seguem um modelo (<strong>Configurações → Saída</strong>) montado com tokens — <code>{prefix}</code> <code>{date}</code> <code>{time}</code> <code>{scene}</code> <code>{profile}</code> <code>{canvas}</code> <code>{marker-count}</code> <code>{counter}</code> — para gravações, replays e imagens estáticas, com pastas próprias para replays e imagens estáticas.","manual.27c3f23547ac":"<strong>Exportar diagnóstico</strong> salva um pacote de detalhes técnicos num arquivo no seu computador, montado a partir de uma lista estrita do que é permitido, para que chaves de transmissão, senhas, caminhos de arquivo e nomes nunca estejam nele. Você pode ler antes o que ele contém; ele fica onde você o salvar e nunca é enviado a lugar nenhum.","manual.5199babf9b90":"Fontes e dispositivos","manual.306121fdda68":"Tudo entre a lente e a tela: sinais de teste, calibração de sincronia, texto vindo de um arquivo, timers, o mapa de atalhos, o mixer a fundo e controles reais de dispositivos.","manual.5eacf1ee941f":"Sinais de teste e calibração de sincronia A/V","manual.920b7abd63cc":"Adicione uma fonte <strong>Sinal de teste</strong> (<strong>Fontes → + → Sinal de teste</strong>): barras de cores, uma grade de calibração, uma varredura de movimento, um tom de referência de 1 kHz a −20 dBFS ou um <strong>flash e bipe</strong> combinados para a sincronia de áudio e vídeo — imagem e som gerados a partir de um único relógio. Confira um projetor, um codificador ou um destino de transmissão sem nenhuma câmera conectada.","manual.788073298328":"Abra a bancada de <strong>Calibração de sincronia A/V</strong> (paleta de comandos → “Calibração de sincronia A/V…”). Escolha a câmera e o microfone a alinhar, aponte a câmera para o programa piscando (a caixa de diálogo pode abrir um projetor em tela cheia para isso) e deixe-a medir por cerca de doze segundos. Ela encontra o flash e o bipe ao longo de vários ciclos e se oferece para aplicar ao microfone o deslocamento medido; o controle deslizante manual continua como alternativa. A medição passa pela sua tela e pelos seus alto-falantes, então os pequenos atrasos deles fazem parte dela — e uma falha diz <em>por quê</em>.","manual.825c83c405fb":"Timers, relógios e texto vindo de um arquivo","manual.85622b429b51":"Uma fonte <strong>Timer</strong> mostra um relógio (com o seu próprio formato e um deslocamento UTC fixo opcional), uma <strong>Contagem regressiva</strong> (por um período de tempo, ou até o próximo horário do dia — no zero ela pode piscar ou trocar de cena), um <strong>Cronômetro</strong> ou o <strong>tempo desde que você entrou ao vivo ou começou a gravar</strong>. Inicie, pause e zere o timer pelas <strong>Propriedades</strong> dele, ou vincule os dois atalhos globais que controlam <em>todos</em> os timers de uma vez (<strong>Configurações → Atalhos</strong>).","manual.fcd4f802968f":"Uma fonte <strong>Texto</strong> pode <strong>ler de um arquivo monitorado</strong> (<strong>Propriedades → Ler de arquivo</strong>): um arquivo <code>.txt</code> inteiro, uma célula de CSV (pelo nome ou número da coluna) ou um valor JSON (um ponteiro como <code>/teams/0/score</code>). As mudanças aparecem em meio segundo. Placares e lower thirds sem nenhum serviço por trás.","manual.1d106549f0ce":"O mapa de atalhos e a mesa do mixer","manual.5d6ad89f147c":"O <strong>Mapa de atalhos</strong> (paleta de comandos → “Mapa de atalhos…”) lista <em>todos</em> os vínculos — ações globais e o push-to-talk e o push-to-mute de cada fonte —, com busca e filtros, e aponta conflitos com honestidade: o mesmo atalho escrito de duas formas aparece como compartilhado, e uma tecla que o sistema recusou (porque outro app a usa) diz isso. <strong>Exportar cola</strong> grava uma referência em Markdown na sua pasta Downloads.","manual.e32e382b9753":"Todo canal do mixer tem <strong>Pan</strong> (balanço estéreo; centralizado é exatamente sem pan, e um clique duplo o zera), <strong>solo PFL</strong> (o monitor ouve só os canais em solo; o mix do programa nunca muda) e uma redução para <strong>mono</strong>. Pan e mono ficam no menu “⋯” do canal; o solo fica no próprio canal.","manual.5dbd70dfc92d":"Dispositivos a fundo: desentrelaçamento e controles da câmera","manual.f8e60899a881":"As <strong>Propriedades</strong> de um dispositivo de captura de vídeo oferecem <strong>Desentrelaçamento</strong> para sinais entrelaçados, como placas de captura alimentadas por câmeras e consoles mais antigos: descartar, bob, linear, mesclar ou adaptativo ao movimento, com a ordem dos campos. Funciona igual em todos os sistemas; mudar a opção reinicia o dispositivo.","manual.34192e6d30fd":"Os <strong>Controles da câmera</strong> — exposição, balanço de branco, foco, zoom, ganho e mais — aparecem nas mesmas <strong>Propriedades</strong> enquanto a câmera está rodando. O Windows e o Linux usam os controles UVC padrão; o macOS mostra o que o sistema informa, o que muitas vezes é nada, e o painel diz isso em vez de mostrar controles deslizantes que não fazem nada. Cada ajuste é salvo num <strong>perfil para aquela câmera</strong>, aplicado de novo quando ela é reconectada ou o app reinicia; <strong>Redefinir perfil</strong> volta aos padrões.","manual.f77f10d8c967":"Automação e controle","manual.726216fb4de1":"Deixe o estúdio se conduzir sozinho com regras, macros e controladores de hardware — todos limitados a uma lista fixa de comandos do estúdio, então nenhuma automação consegue apontar um arquivo, iniciar um programa ou acessar a internet.","manual.193521bd4921":"Regras, macros e variáveis","manual.e8ee7ccab125":"Abra <strong>Ferramentas → Regras de automação e macros…</strong> e adicione uma regra. Escolha um de nove gatilhos (uma troca de cena, a transmissão começando ou parando, a gravação começando ou parando, um erro de fonte, um nível de áudio cruzando um limite, o sistema ficando ocioso, uma janela ganhando o foco, um horário do dia ou um arquivo monitorado mudando), adicione condições (o valor de uma variável, ao vivo, gravando) e escolha uma ação do estúdio. Toda regra começa <strong>desativada</strong>: ative-a para armá-la.","manual.5deaa7ba718f":"Monte uma macro como uma lista nomeada de passos — executar uma ação, esperar, definir uma variável — com um número de repetições e um atalho global opcional. Execute-a pelo app, por um atalho, por uma regra ou pela API de controle remoto.","manual.30ee5b1326f2":"Defina uma <strong>variável</strong> do estúdio numa macro e use-a como <code>{{name}}</code> dentro de qualquer fonte de Texto: o texto muda no momento em que a macro define o valor.","manual.5eb10fc04538":"Controladores: MIDI, OSC e o painel touch","manual.ba0c838f1688":"Abra <strong>Ferramentas → Controle MIDI…</strong> e ensine a ele um pad, botão giratório ou fader para uma ação, uma macro, uma troca de cena, um fader do mixer ou um silenciamento — com luzes e faders motorizados que acompanham o estado real do estúdio. Nenhuma porta MIDI é aberta até você escolher uma.","manual.cc993cb0d974":"Ative <strong>Escutar OSC</strong> para que controladores no estilo TouchOSC e mesas de iluminação enviem endereços como <code>/scene/switch</code>, <code>/record/start</code>, <code>/macro/run</code> e <code>/mixer/vol</code>. Vem desligado por padrão e só escuta neste computador, a menos que você permita a sua rede. O OSC não tem senha própria.","manual.134e5f4269f9":"Abra <strong>Ferramentas → Painel LAN e tally…</strong> para servir uma página de controle — botões de cena com tally ao vivo, faders do mixer e teclas de ação — a qualquer celular por um QR code. Toda requisição exige a senha, e ele só escuta neste computador, a menos que você permita a sua rede. A página de tally fica vermelha ou verde em tela cheia; adicione <code>?scene=NAME</code> para acompanhar uma cena.","manual.fc4cd96b860d":"Acordes de atalho e camadas","manual.ec4a9a334753":"Num campo de atalho, vincule um atalho simples (Ctrl+Shift+M) ou um acorde de duas etapas (Ctrl+K, depois 3) — a segunda tecla só é capturada enquanto o acorde está esperando. Dê a um vínculo uma <strong>Camada</strong> para que ele só funcione enquanto essa camada estiver ativa; uma camada continua ativa até você trocá-la.","manual.70ad05980925":"Câmeras e o espelho do programa","manual.24b33b058b99":"Abra <strong>Ferramentas → Câmeras PTZ…</strong>, adicione uma câmera pelo seu endereço VISCA over IP, salve predefinições nomeadas de pan, tilt e zoom e vincule uma predefinição a uma cena, para que ir para essa cena chame o enquadramento. O PTZ fica na sua rede, e uma câmera só existe porque você digitou o endereço dela: nada é procurado.","manual.c9d86b995c5a":"Abra <strong>Ferramentas → Mostrar espelho do programa…</strong> e liste os passos — uma cena, quanto tempo ela fica e ações opcionais —, avançando manualmente ou automaticamente, com um “a seguir” ao vivo e o tempo restante. Um espelho troca de cena do jeito comum, que pode ser desfeito, e nunca edita a sua coleção de cenas.","manual.5c94bed2d737":"<strong>Observação:</strong> toda regra, macro, vínculo MIDI ou OSC, botão do painel e passo do espelho passa pela mesma lista fixa de comandos da API de controle remoto, então nenhum controlador consegue fazer o que os próprios botões do app não fazem. Toda escuta de rede vem desligada por padrão e fica neste computador, a menos que você permita a sua rede, e as configurações de OSC e do painel avisam que o tráfego de rede não é criptografado antes de a porta abrir.","manual.1f3fd1c7ddc9":"Multistream para várias plataformas","manual.dcac0a03a29b":"Transmita para várias plataformas ao mesmo tempo — direto do seu computador, sem nenhum serviço intermediário no meio.","manual.42d9628818da":"Adicione dois ou mais destinos de transmissão em <strong>Configurações → Transmissão</strong> e ative cada um deles.","manual.4144fe0d9694":"Dê a uma plataforma suas próprias configurações de codificador se ela precisar de um bitrate diferente.","manual.cb21d6bb96be":"Clique em <strong>Ficar ao vivo</strong>: você transmite para todos os destinos ativados ao mesmo tempo. A doca de estatísticas mostra a saúde e o bitrate de cada destino, e a falha de um destino nunca derruba os outros.","manual.aba9a5f55973":"Opcionalmente, grave ao mesmo tempo uma cópia local com faixas separadas e salve replays com o atalho de replay enquanto transmite.","manual.af9343c245a7":"<strong>Gratuito hoje:</strong> todos os recursos — multistream, SRT e WHIP, todos os filtros, scripts, replay, os pacotes de transições e a API de controle remoto — são gratuitos hoje, para todos. Versões futuras podem ser vendidas.","manual.c08320c45003":"Confiabilidade e visibilidade da transmissão","manual.532ab322d03c":"Ensaie, meça e explique o seu programa. Tudo aqui vem desligado ou neutro por padrão, e nada disso vai para a internet.","manual.80390ae1a9d7":"O simulador de rede","manual.7e620ced841e":"Em <strong>Configurações → Transmissão</strong>, abra o <strong>Simulador de rede (ensaios)</strong> e escolha um <strong>Perfil</strong> — <strong>Wi-Fi de hotel</strong>, <strong>Hotspot móvel</strong> ou <strong>Personalizado</strong>, com seus próprios valores de <strong>Largura de banda</strong>, <strong>Latência</strong>, <strong>Jitter</strong> e horários programados de <strong>Queda</strong>. Ele afeta só a saída local de um ensaio, então você pode praticar reconexões, multistream e escolhas de bitrate; ele nunca consegue deixar uma transmissão real mais lenta.","manual.b22d8c51e0bd":"Modo de ensaio","manual.083772633b86":"Aperte o botão violeta <strong>Ensaiar</strong> para rodar todo o pipeline — compositor, codificador, muxer e a lógica real de reconexão — para um destino local substituto, com <strong>nada saindo do computador</strong>. Um selo <strong>ENSAIO</strong> marca todos os controles ao vivo, e as suas chaves de transmissão nem chegam a ser lidas, então você pode ensaiar antes de tê-las. Você também pode gravar o ensaio.","manual.184d64047c4c":"<strong>Dica:</strong> combine um ensaio com o simulador de rede para praticar reconexões numa conexão fraca e instável bem antes do dia.","manual.d2381a584d24":"A linha do tempo de quadros perdidos","manual.a6a72c5410a8":"A <strong>Linha do tempo da sessão</strong> registra a sessão inteira — tempo de renderização, fila do codificador, bitrate e quadros perdidos de cada destino, reconexões, trocas de cena, marcadores e alarmes — num único gráfico com zoom. Enquanto a doca de estatísticas mostra o <em>agora</em>, a linha do tempo responde depois à pergunta “o que aconteceu no minuto 43?”.","manual.6e9fee1e85fa":"O relatório da sessão e o benchmark de codificadores","manual.9dd812cbf648":"Ative <strong>Gravar um relatório da sessão (HTML + Markdown) ao lado da gravação</strong> em <strong>Configurações → Transmissão</strong> para ter um resumo local quando a sessão terminar: tempo no ar, bitrate médio e de pico por destino, o tempo fora do ar, as reconexões, os marcadores, os alarmes e o local da gravação. Ele fica no seu computador e vem desligado por padrão.","manual.a9e574b7bd8d":"Use <strong>Executar benchmark de encoders…</strong> para medir codificações curtas com cada codificador, predefinição e resolução que o seu computador tem — cerca de um minuto, totalmente offline — e depois clique em <strong>Aplicar às configurações de gravação</strong> a partir do resultado. As falhas são listadas, não escondidas, e o benchmark se recusa a rodar enquanto você está ao vivo ou gravando.","manual.fae310275ed2":"Fontes só na transmissão ou só na gravação","manual.191da176dd0d":"Na linha de uma fonte, use <strong>Mostrar na transmissão</strong> / <strong>Ocultar na transmissão</strong> e <strong>Mostrar na gravação</strong> / <strong>Ocultar na gravação</strong> para manter alertas e chat na transmissão ao vivo enquanto a gravação fica limpa, a partir de uma única tela. O botão principal do olho continua controlando tudo, e a prévia, os projetores e a multivisualização sempre mostram o programa inteiro.","manual.46bad2cb618f":"Câmera virtual","manual.69ebe5277092":"Use o seu programa como webcam em qualquer app de videochamada. <strong>Só no Windows na 1.2.1.</strong>","manual.ba2b6aa952f7":"Clique em <strong>Iniciar câmera virtual</strong> em <strong>Controles</strong>. O Freally Capture adiciona uma câmera do sistema chamada <strong>“Freally Capture Virtual Camera”</strong>.","manual.cb3cb4585f19":"No Zoom, no Meet, no Discord ou no Teams, escolha essa câmera nas configurações de vídeo: o seu programa vira a webcam.","manual.83db59f4a370":"Clique em <strong>Parar câmera virtual</strong> para removê-la.","manual.91c51d55639b":"<strong>Por sistema:</strong> no <strong>Windows</strong>, a câmera é registrada para o seu usuário, sem direitos de administrador, e é removida quando você a para. Ela <strong>ainda não tem assinatura de código</strong>, então o Windows pode avisar sobre ela e um app de videochamada mais restritivo pode recusá-la; ainda falta um teste completo dentro de uma chamada de verdade. As câmeras para <strong>macOS</strong> e <strong>Linux</strong> são componentes separados que <em>não estão nesta versão</em>. O Freally Capture nunca instala um componente de sistema sem perguntar, em nenhum sistema.","manual.98839b8e6880":"Fonte de navegador","manual.3ba821584b20":"Coloque uma página da web ao vivo — uma sobreposição de alertas, um placar, um widget de chat — direto numa cena.","manual.895f07f428cd":"Em <strong>Fontes</strong>, clique em <strong>+</strong> e escolha <strong>Navegador</strong>.","manual.868ee19e975e":"Cole um endereço <strong>http://</strong> ou <strong>https://</strong> e defina o tamanho e a taxa de quadros em que ele será renderizado.","manual.292e94b0a782":"Na primeira vez, o Freally Capture se oferece para instalar o componente <strong>Ambiente de execução do navegador</strong>. Ele é baixado quando você pede e verificado pelo seu hash — nunca vem embutido no app —, e você pode removê-lo de novo em <strong>Ferramentas → Componentes</strong>.","manual.cd6d7fbd46ee":"<strong>Só http e https carregam.</strong> A regra vale para toda mudança de página, não só para o endereço que você digita: se uma página tentar ir para <code>file://</code>, <code>javascript:</code> ou <code>data:</code> — por um redirecionamento, um script, um pop-up ou um frame —, a mudança é <strong>cancelada</strong>, então uma página não consegue ler os seus arquivos. No Windows, a página roda na sandbox do Chromium. O ambiente de execução <strong>ainda não tem assinatura de código</strong>. O som da página ainda não é capturado: esta versão é só imagem.","manual.9c0c8f127dd9":"Captura de jogos","manual.2c08692420b8":"Capture um jogo em tela cheia exclusiva que a captura de janela comum não consegue ver. <strong>Só no Windows.</strong>","manual.9d162e3861e9":"Em <strong>Fontes</strong>, clique em <strong>+</strong> e escolha <strong>Captura de Jogo</strong>. <strong>Leia o aviso primeiro</strong>: ele explica o risco em palavras simples.","manual.4264b41a7732":"Aceite o risco <em>para aquele jogo</em>, depois escolha na lista o jogo que está rodando.","manual.ab3e826e90f1":"O Freally Capture carrega um pequeno hook nesse jogo e captura os quadros na própria taxa de quadros do jogo.","manual.082fd06e18f9":"<strong>Leia isto antes de usar.</strong> A captura de jogos funciona <strong>carregando uma DLL dentro do jogo</strong>. Softwares antitrapaça e antivírus podem tratar isso como adulteração, e isso pode fazer uma conta ser <strong>banida</strong>. Nada é carregado automaticamente: você concorda <strong>um jogo de cada vez</strong>, e essa concordância nunca pode ser usada para outro jogo — e nunca viaja dentro de uma coleção de cenas compartilhada. Se um jogo recusar o hook, o Freally Capture passa para a <strong>Captura de Janela</strong> comum com uma mensagem, em vez de falhar. Jogos HDR e jogos Direct3D 12 também usam a Captura de Janela. No macOS e no Linux, esta fonte não é oferecida.","manual.43fae75af922":"Buffer de replay","manual.40bc664c1c0b":"Mantenha os últimos momentos na memória, para que um atalho salve o que acabou de acontecer.","manual.7a69241c10c2":"Clique em <strong>Iniciar buffer de replay</strong> em <strong>Controles</strong>. O Freally Capture guarda os últimos segundos num buffer de tamanho fixo.","manual.684aecea2ba0":"Vincule um atalho global de <strong>Salvar replay</strong> em <strong>Configurações</strong>.","manual.66c44777e965":"Aperte-o para salvar os últimos segundos num arquivo — sem interromper a sua transmissão nem a sua gravação principal. Uma mensagem “Replay salvo” confirma.","manual.4b598d5daf11":"O teleprompter","manual.b7fc474ded62":"Um roteiro com rolagem suave para quem está diante da câmera — num painel do app, num projetor em tela cheia que pode ser espelhado e no painel touch da rede local, tudo ao mesmo tempo.","manual.f1c548f77750":"Abra o teleprompter em <strong>Ferramentas</strong>, digite ou cole o seu roteiro e defina a velocidade e a fonte. Ajuste o ritmo em <strong>caracteres por segundo</strong>, ou mude para <strong>BPM</strong> (50–250 batidas por minuto) para ler letras de música no tempo da música; qualquer uma das duas mudanças reajusta o ritmo de uma rolagem em andamento.","manual.3a86eb91938d":"<strong>Marcas de pausa:</strong> digite <code> -- </code> para uma pausa breve ou <code> --N </code> para uma pausa de N segundos e isso vira uma única marca — o cursor passa por cima dela, um único Delete ou Backspace a remove, e copiar e colar a mantêm inteira.","manual.dc7539148aed":"<strong>Iniciar contagem regressiva:</strong> arme uma contagem opcional de 3-2-1, mostrada tanto na prévia do operador quanto no projetor, para que quem lê tenha um instante antes de o texto se mover.","manual.f5113c573ac4":"<strong>Abra o projetor</strong> para quem vai ler (o modo espelho o inverte para vidro de beam splitter). Abri-lo fecha a janela do operador, então você pode conduzir a transmissão pela janela principal enquanto a pessoa lê; com uma contagem regressiva armada, o projetor volta ao início, faz a contagem e começa a rolar. Reproduza, pause, pare, volte, avance e recomece pelos controles na tela, por um atalho, por MIDI, por OSC ou pelo painel LAN — todos os controles ficam em sincronia.","manual.5298a60b0152":"<strong>Ler em voz alta</strong> faz uma prévia do roteiro com a própria voz do seu sistema: as vozes embutidas do Windows, as do macOS e, no Linux, o <code>spd-say</code> ou o <code>espeak-ng</code>, quando instalados. Nenhum mecanismo de fala vem embutido.","manual.5de1b5efa245":"O <strong>Preenchimento automático</strong> sugere palavras e frases em cinza-claro enquanto você digita; aperte Tab para aceitar. Cada um dos 18 idiomas tem seu próprio dicionário no seu computador, carregado só para o idioma em que você está escrevendo.","manual.7fb5d22a1670":"Controle remoto","manual.b2ba73efdcec":"Comande o estúdio a partir de um Stream Deck ou de um controlador no estilo Companion — desligado por padrão, protegido por senha, no seu próprio computador.","manual.6396674fcd28":"Abra <strong>Configurações → Controle remoto</strong>, ative a <strong>API WebSocket</strong> (desligada por padrão) e defina uma <strong>senha</strong>.","manual.56e0d6d295bb":"Ela escuta em <code>127.0.0.1</code> — só neste computador —, a menos que você permita explicitamente a sua rede.","manual.344e52e3eba1":"Aponte um cliente Companion ou Stream Deck para o endereço mostrado. Troque de cena, rode transições, silencie e reative o som, inicie e pare a gravação e salve replays com botões físicos.","manual.6664edd9ad4c":"Convidados remotos e produção do programa","manual.75ce17238f9b":"Transforme uma sessão com convidados remotos num programa produzido: até oito convidados, desenho sobre o programa ao vivo, uma sala de espera, deixas privadas, a conexão de cada convidado num relance e uma grade automática. Tudo aqui vem desligado ou sem atalho por padrão, e nada se conecta até você convidar alguém.","manual.02d9e34002c8":"Sessões com vários convidados","manual.5a6c2ec7640d":"Inicie uma sessão com convidados remotos e compartilhe o link do convite ou o QR code dele: <strong>você e até oito convidados</strong>, uma galeria de um a nove. Cada convidado é um bloco com seus próprios controles de silenciar, qualidade da conexão, canal de deixas e um clique para colocá-lo no ar.","manual.34a323a45540":"O convidado abre o link num navegador — nada para instalar — e toca em <strong>Entrar</strong> para enviar a câmera e o microfone. Um convidado que tem o Freally Capture pode abrir o mesmo convite no app. Um convite expira depois do tempo que você escolher.","manual.4e31042e4a6f":"<strong>Observação:</strong> imagem e som vão direto entre você e cada convidado, ponto a ponto e criptografados no trajeto; só a negociação da conexão passa por um serviço de sinalização público. As sessões foram testadas com quatro convidados; mais do que isso depende da sua largura de banda e do seu processador.","manual.33ff43cd0616":"Telestrator: desenhe no programa ao vivo","manual.d29f651d6eb9":"Abra o <strong>Telestrator</strong> e escolha uma ferramenta — <strong>Caneta</strong>, <strong>Marca-texto</strong>, <strong>Seta</strong> ou <strong>Elipse</strong> — e desenhe direto no programa. Suas marcas fazem parte da imagem no momento em que você as desenha, então elas aparecem na gravação e na transmissão, não só na sua prévia.","manual.9aa7fc0273fb":"Deixe as marcas <strong>Esmaecer</strong> depois de um tempo, ou mude para o <strong>Modo lousa</strong> para <strong>Manter</strong> as marcas até você limpá-las. O desenho segue a pressão de uma mesa digitalizadora, e <strong>Limpar marcas</strong> pode ser vinculado a um atalho (sem atalho por padrão).","manual.fc81cd8d37ae":"A sala de espera","manual.c87beb96ec64":"Ative a <strong>Sala de espera</strong> e os novos convidados esperam fora do ar enquanto você confere a câmera e o microfone deles na <strong>Prévia da sala de espera</strong>. Quando estiverem prontos, clique em <strong>Colocar no ar</strong>. O convidado vê um banner “você está na sala de espera”, no app ou na página da web.","manual.1d47c8224f50":"Deixas e conversa","manual.569d461035c1":"Envie a um convidado uma <strong>Deixa</strong> privada — com predefinições como <strong>30 segundos</strong>, <strong>Finalize</strong>, <strong>Você é o próximo</strong> e <strong>Fale mais alto</strong> — pelo canal ponto a ponto que a sessão já tem. O convidado a vê com uma contagem regressiva ao vivo, nunca no programa.","manual.c66c9d5359bf":"O painel de qualidade da conexão","manual.4541cc1ee0f5":"Acompanhe ao vivo a conexão de cada convidado — tempo de ida e volta, perda de pacotes, a resolução e a taxa de quadros que você recebe e o jitter — com um selo verde, âmbar ou vermelho e um pequeno gráfico de histórico, para que uma conexão enfraquecendo apareça antes que os seus espectadores percebam.","manual.bf8e764221e5":"Grades automáticas de convidados","manual.ffe3c227cdfc":"Ative a <strong>Grade automática</strong> para manter os convidados no ar numa grade organizada de um a nove, que se reorganiza sozinha quando convidados entram, saem ou são colocados no ar, ou aperte o botão de organizar para fazer isso agora. Cada lugar publica o nome do seu convidado como uma variável <code>{{guestN}}</code>, então uma fonte de título vira um crachá de nome que se atualiza sozinho.","manual.e8630fabd4e5":"Gestão do estúdio e fluxo de trabalho","manual.c8c487196725":"Torne um layout inteiro portátil e compartilhável, guarde versões nomeadas das suas cenas, personalize o tema do app e deixe suas ações favoritas a um toque — tudo no seu computador, sem servidor.","manual.f87995a7cf6c":"Pacotes de cenas e versões","manual.074bb2bf9453":"Abra a caixa de diálogo do espaço de trabalho em <strong>Coleção de cenas → Gerenciar coleções de cenas…</strong>: as ferramentas de pacote, comparação, instantâneo, backup e layout de docas estão todas lá.","manual.8dce3a052a05":"Clique em <strong>Exportar pacote…</strong> para reunir a coleção atual e os arquivos dela (imagens, mídias, LUTs, máscaras, fontes tipográficas) num único <code>.fcappack</code> portátil. Endereços da web e caminhos de rede são listados como <em>externos</em> em vez de embutidos, e as fontes tipográficas são sinalizadas por causa das licenças.","manual.c1bba88df9c5":"Clique em <strong>Importar pacote…</strong> e escolha um <code>.fcappack</code>: ele chega como uma nova coleção, encontra os seus arquivos neste computador e passa a ser a coleção ativa.","manual.69e7b9f6e8ab":"Clique em <strong>Comparar e mesclar…</strong> para comparar a coleção atual com outra coleção, um pacote ou um instantâneo. Revise as cenas, fontes, transformações, filtros e visibilidade adicionados, removidos e alterados, e depois escolha exatamente quais mudanças trazer. Escolher uma cena traz as fontes que ela usa.","manual.862a75c84629":"Clique em <strong>Instantâneos…</strong>, dê nome a um ponto de controle e escolha <strong>Salvar instantâneo</strong>. <strong>Restaurar</strong> o traz de volta depois — o seu layout atual é salvo antes como instantâneo, então uma restauração nunca é um caminho sem volta. São guardados até 50 instantâneos, com o uso de disco mostrado.","manual.8058b1480d14":"<strong>Dica:</strong> os instantâneos são um histórico nomeado ao lado do salvamento automático e do desfazer. Tire um antes de uma mudança arriscada, e você sempre terá um ponto identificado para onde voltar.","manual.1d55a62a5fdf":"Backup, restauração e modo portátil","manual.250b89a976de":"Na caixa de diálogo do espaço de trabalho, clique em <strong>Backup e restauração…</strong> e depois em <strong>Exportar backup…</strong> para salvar tudo — configurações, perfis e coleções de cenas — num único arquivo <code>.fcapbackup</code>.","manual.560e7e269f11":"Num computador novo, clique em <strong>Restaurar de um backup…</strong>, marque o que trazer (<strong>Configurações</strong>, <strong>Coleções de cenas</strong>, <strong>Perfis</strong>) e escolha <strong>Restaurar selecionados</strong>. Depois, reinicie o Freally Capture para carregar as coleções e os perfis restaurados.","manual.5b26da4b8793":"Para rodar a partir de um pendrive, coloque um arquivo chamado <code>freally-portable.txt</code> ao lado do programa: todos os dados dele passam a ficar na pasta do programa em vez do seu perfil de usuário. <strong>Configurações → Sobre</strong> mostra se o modo portátil está ativo e onde ficam os dados.","manual.a31a49d41d7d":"<strong>Observação:</strong> chaves de transmissão e senhas nunca são gravadas num backup — digite-as de novo depois de restaurar.","manual.5b446c4ea972":"Temas, layouts e ações rápidas","manual.8eea476bde73":"Abra <strong>Configurações → Aparência</strong> e escolha o tema <strong>Personalizado</strong> para editar a paleta, com <strong>avisos de contraste</strong> ao vivo, e depois use <strong>Exportar .fctheme…</strong> ou <strong>Importar .fctheme…</strong> para compartilhá-lo.","manual.7cc0bc3a4e74":"Em <strong>Layouts de docas</strong>, na caixa de diálogo do espaço de trabalho, salve a disposição atual com um nome e clique num layout salvo para mudar para ele.","manual.c9044c09b979":"Em <strong>Configurações</strong>, digite em <strong>Pesquisar configurações…</strong> para ir direto a qualquer configuração; um marcador mostra quais categorias você alterou desde que abriu a janela.","manual.a4640858ad4d":"Escolha <strong>Ferramentas → Ações rápidas…</strong> para abrir a grade de botões. Clique em <strong>Editar</strong> e depois em <strong>Adicionar botão</strong>, defina o rótulo e a cor de cada botão e adicione <strong>páginas</strong>. Um botão pode trocar de cena, executar uma macro, tocar um pad da mesa de efeitos sonoros ou executar um comando do estúdio.","manual.74ff6472576d":"<strong>Dica:</strong> os botões de ações rápidas executam os mesmos comandos do estúdio que os atalhos, e a grade é compartilhada com o painel touch da rede local: configure uma vez e ela também estará no seu celular.","manual.74a883a037bc":"Configurações","manual.5feaf4600834":"Perfis, coleções de cenas, atalhos e idioma. Tudo é gratuito hoje, então não há nada para ativar. <strong>Configurações</strong> é uma única janela com categorias — Geral, Aparência, Transmissão, Saída, Replay, Atalhos, Rede, Acessibilidade e Sobre — aberta pela <strong>barra de menus</strong> (Arquivo, Editar, Exibir, Docas, Perfil, Coleção de cenas, Ferramentas e Ajuda).","manual.9f6a04e85e39":"<strong>Aplicar quer dizer aplicar.</strong> A janela de Configurações edita uma cópia: nada muda até você clicar em <strong>Aplicar</strong> ou <strong>OK</strong>, e <strong>Cancelar</strong> devolve exatamente o que você tinha, incluindo a prévia do tema.","manual.3fc0968ef6f9":"<strong>Perfis e coleções de cenas:</strong> mantenha configurações separadas — “Transmissão” e “Gravação local”, por exemplo — e alterne entre elas sem reiniciar, pelos menus <strong>Perfil</strong> e <strong>Coleção de cenas</strong>.","manual.ce6f52861bdb":"<strong>Atalhos:</strong> vincule cada ação a partir de uma lista que não permite conflitos — escolha um atalho para uma ação e ele some da lista de todas as outras ações, então dois recursos nunca dividem uma tecla. <strong>Nenhum</strong> o libera de novo.","manual.be52349f05be":"<strong>Acessibilidade:</strong> escolha as cores dos medidores do mixer, incluindo um conjunto seguro para daltônicos. O app inteiro funciona pelo teclado, e os leitores de tela anunciam a entrada ao vivo, a gravação, a reconexão e os quadros perdidos.","manual.a79c94673558":"<strong>Idioma:</strong> escolha um de 18 idiomas; o app muda na hora, e o árabe é lido da direita para a esquerda.","manual.59274c49ac87":"Relatar um problema","manual.c02ed8aec89d":"Você decide se um problema chega ao desenvolvedor, e vê exatamente o que seria enviado.","manual.4ed327c34aeb":"Quando o app mostra um erro causado por ele mesmo, aparece um botão <strong>Relatar</strong> ao lado.","manual.95da4b53fdcc":"Depois de um travamento, a próxima abertura oferece <strong>Relatar</strong> ou <strong>Dispensar</strong>.","manual.6207904599f4":"<strong>Relatar</strong> abre no seu navegador a página de relatório do Freally Capture neste site, com os dados técnicos já preenchidos: você pode lê-los, mas não alterá-los. Acrescente o que você estava fazendo e, se quiser, um endereço de e-mail. Nada é enviado a menos que você aperte <strong>Enviar</strong> ali.","manual.6acd4e789ccd":"Nada é enviado em segundo plano, nunca, e <strong>Dispensar</strong> não envia absolutamente nada.","manual.69bd78234ffb":"Privacidade e a rede","manual.42f9b04c2640":"O Freally Capture não tem conta nem telemetria, e não existe nenhum serviço de nuvem nosso. Aqui está exatamente o que vai para a internet, e o que não vai.","manual.81fe73d241a8":"<strong>Sem conta, sem telemetria.</strong> O app nunca pede que você faça login e nunca envia as suas cenas, gravações ou qualquer dado de uso para lugar nenhum.","manual.3735a28566e9":"<strong>Sua transmissão vai direto para a plataforma.</strong> Ela sai do seu computador para os serviços que você configurou — não há nenhum servidor intermediário nosso.","manual.512b8fa00684":"<strong>Suas gravações ficam no seu computador,</strong> na pasta que você escolher. Nada é enviado.","manual.c299fcfa1fde":"<strong>Suas chaves de transmissão ficam no seu computador,</strong> exibidas mascaradas e enviadas só ao serviço para o qual você transmite.","manual.414a08bd0219":"<strong>Convidados remotos se conectam ponto a ponto.</strong> Só a negociação da conexão da sessão passa por um serviço de sinalização público, e só quando você inicia uma sessão.","manual.20c95c4687b3":"<strong>Uma sobreposição de chat lê o chat público</strong> do canal para o qual você a aponta, do jeito que um espectador sem login leria — sem conta, chave ou login.","manual.efe87d55bed1":"<strong>Dois componentes só são baixados quando você precisa deles pela primeira vez:</strong> o ffmpeg, para os codecs que as plataformas exigem, e o ambiente de execução do navegador, para a fonte de navegador. Cada um vem do seu próprio fornecedor e é verificado antes do uso.","manual.3601a272b3b0":"<strong>Uma verificação de atualizações</strong> baixa um único arquivo pequeno uma vez a cada abertura, e quando você escolhe <strong>Verificar atualizações…</strong>. Nada sobre você ou o seu computador é enviado junto, e nada é instalado a menos que você diga sim.","manual.11abc96d8e21":"<strong>Um relatório de problema só é enviado quando você aperta Enviar</strong> na página de relatório, depois de ler o que ele contém (veja <a href=\"#report\">Relatar um problema</a>).","manual.804fa6536d40":"<strong>Sem IA.</strong> Todos os filtros — redução de ruído, chroma key, mapeamento de tons — são processamento de sinal clássico. O app não contém nenhum modelo de aprendizado de máquina e não baixa nenhum."}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
